  if (!token || !/^bearer$/i.test(scheme)) {
    return res.status(401).json({ error: 'unauthorized' });
  }
  let payload;
  try {
    payload = jwt.verify(token, SECRET, {
      algorithms: ['HS256'],
      issuer: 'your-issuer',
      audience: 'your-api',
      maxAge: '1h',
    });
  } catch {
    return res.status(401).json({ error: 'unauthorized' });
  }
  req.user = { id: payload.sub, roles: payload.roles || [] };
  next();
}

module.exports = { requireAuth };
```

